import { article as articleEntries } from "@ui8kit/app-shared/data/article";

const POSTS_FIELDS = {
  "id": "id",
  "title": "title.en",
  "excerpt": "metadata.excerpt.value",
  "category": "metadata.category.value",
  "author": "metadata.author.value",
  "date": "metadata.date.value",
  "minutes": "metadata.minutes.value",
  "icon": "metadata.icon.value",
} as const;
const TOPICS_FIELDS = {"id":"id","title":"title.en","value":"metadata.value.value"} as const;
const ARTICLE_FIELDS = {"id":"id","title":"title.en","text":"metadata.text.value","quote":"metadata.quote.value"} as const;

const posts = fromCodex<Post>(postsEntries, POSTS_FIELDS);
const topics = fromCodex<PostTopic>(topicsEntries, TOPICS_FIELDS);
const article = fromCodex<Section>(articleEntries, ARTICLE_FIELDS);

export function PlainPage() {
  return (
    <>
      <PostHeader
        id="plain-postheader"
        post={posts.find((i) => i.id === "post-static-first")!}
        labels={ui.content.labels}
        layout="start"
        cover="hide"
        meta="full"
        tone="default"
      />
      <ArticleBody
        id="plain-article"
        title={ui.vibe.article.title}
        sections={article}
        tocTitle={ui.vibe.article.toc}
        layout="column"
        quotes="hide"
        tone="default"
        landmarkLabel={uniqLabel(tpl(ui.blocks.landmark, ui.blocks.names.article, ui.blocks.variants.article.plain))}
      />
      <PostGrid
        id="plain-posts"
        title={ui.content.posts.title}
        posts={posts}
        labels={ui.content.labels}
        filter={{ topics, label: ui.vibe.posts.topics, topic: "", mode: "none" }}
        action={{ label: ui.content.posts.action, href: "#/" }}
        layout="grid"
        cols="1-3"
        media="image"
        meta="full"
        tone="default"
        density="default"
        landmarkLabel={uniqLabel(tpl(ui.blocks.landmark, ui.blocks.names.posts, ui.blocks.variants.posts.grid))}
      />
    </>
  );
}

